body:
I am trying to lower a Calyx design (generated by Polygeist) into SystemVerilog using the `lower-calyx-to-hw` pass. However, the compiler consistently rejects `calyx.seq_mem` (and `calyx.memory`), either failing to legalize it or complaining about the address port count.

Furthermore, attempting to bypass this by creating a blackbox `calyx.component` and instantiating it via `calyx.instance` results in either a legalization failure or a `Segmentation fault` during the topological traversal.

### To Reproduce

Here are the different approaches I have tested, all resulting in failures:

#### Attempt 1: The original Polygeist output (8 ports)

Polygeist generates an 8-port `seq_mem` (including `content_en` and `reset`).

```mlir
"builtin.module"() ({
  "calyx.component"() <{function_type = (i64, i1, i1, i1, i1) -> (), portAttributes = [{}, {clk}, {reset}, {go}, {done}], portDirections = -16 : i5, portNames = ["in0", "clk", "reset", "go", "done"], sym_name = "main"}> ({
  ^bb0(%arg0: i64, %clk: i1, %reset: i1, %go: i1, %done: i1):
    %mem:8 = "calyx.seq_mem"() <{addrSizes = [1], sizes = [2], sym_name = "my_sram", width = 64 : i64}> : () -> (i1, i1, i1, i1, i1, i64, i64, i1)

    "calyx.wires"() ({
    ^bb0:
      // Dummy assignment to prevent "empty component" verifier error
      "calyx.assign"(%done, %go) : (i1, i1) -> ()
    }) : () -> ()

    "calyx.control"() ({
    ^bb0:
    }) : () -> ()
  }) {toplevel} : () -> ()
}) {calyx.entrypoint = "main"} : () -> ()
```

Error: `'error: 'calyx.seq_mem' op couldn't convert to core primitive`

#### Attempt 2: Trimming/Expanding ports to match CIRCT assumptions (6, 7, or 9 ports)

Assuming the issue was an incorrect port signature, I tried adjusting the return types to 6, 7, and 9 ports (with and without implicit clk/reset).

```mlir
"builtin.module"() ({
  "calyx.component"() <{function_type = (i64, i1, i1, i1, i1) -> (), portAttributes = [{}, {clk}, {reset}, {go}, {done}], portDirections = -16 : i5, portNames = ["in0", "clk", "reset", "go", "done"], sym_name = "main"}> ({
  ^bb0(%arg0: i64, %clk: i1, %reset: i1, %go: i1, %done: i1):
    // 7 ports test:
    %mem:7 = "calyx.seq_mem"() <{addrSizes = [1], sizes = [2], sym_name = "my_sram", width = 64 : i64}> : () -> (i64, i1, i1, i1, i64, i1, i1)

    "calyx.wires"() ({
    ^bb0:
      // Dummy assignment to prevent "empty component" verifier error
      "calyx.assign"(%done, %go) : (i1, i1) -> ()
    }) : () -> ()

    "calyx.control"() ({
    ^bb0:
    }) : () -> ()
  }) {toplevel} : () -> ()
}) {calyx.entrypoint = "main"} : () -> ()
```

Error: `error: 'calyx.seq_mem' op incorrect number of address ports, expected 1`

```mlir
"builtin.module"() ({
  "calyx.component"() <{function_type = (i64, i1, i1, i1, i1) -> (), portAttributes = [{}, {clk}, {reset}, {go}, {done}], portDirections = -16 : i5, portNames = ["in0", "clk", "reset", "go", "done"], sym_name = "main"}> ({
  ^bb0(%in0: i64, %clk: i1, %reset: i1, %go: i1, %done: i1):
    %false = "hw.constant"() <{value = false}> : () -> i1
    %c0_i64 = "hw.constant"() <{value = 0 : i64}> : () -> i64

    %read_data, %read_done, %write_done, %addr0, %write_data, %write_en, %read_en, %mem_clk, %mem_reset = "calyx.seq_mem"() <{
      addrSizes = [1],
      sizes = [2],
      sym_name = "my_sram",
      width = 64 : i64,
      resultSegmentSizes = array<i32: 1, 1, 1, 1, 1, 1, 1, 1, 1>
    }> : () -> (i64, i1, i1, i1, i64, i1, i1, i1, i1)

    "calyx.wires"() ({
    ^bb0:
      "calyx.assign"(%mem_clk, %clk) : (i1, i1) -> ()
      "calyx.assign"(%mem_reset, %reset) : (i1, i1) -> ()
      "calyx.assign"(%addr0, %false) : (i1, i1) -> ()
      "calyx.assign"(%write_data, %c0_i64) : (i64, i64) -> ()
      "calyx.assign"(%write_en, %false) : (i1, i1) -> ()
      "calyx.assign"(%read_en, %false) : (i1, i1) -> ()
      "calyx.assign"(%done, %write_done) : (i1, i1) -> ()
    }) : () -> ()

    "calyx.control"() ({
      "calyx.seq"() ({
      }) : () -> ()
    }) : () -> ()
  }) {toplevel} : () -> ()
}) {calyx.entrypoint = "main"} : () -> ()
```

Error: `error: 'calyx.seq_mem' op incorrect number of address ports, expected 1`

(The verifier seems to miscalculate the dynamic address ports). Adding `resultSegmentSizes` did not resolve this.

#### Attempt 3: Using `calyx.memory` instead

I tried casting it to a combinational memory `calyx.memory` with a strict 6-port signature `(read_data, done, addr0, write_data, write_en, clk)`.

```mlir
module attributes {calyx.entrypoint = "main"} {
  calyx.component @main(%clk: i1 {clk}, %reset: i1 {reset}, %go: i1 {go}) -> (%done: i1 {done}) {
    %mem.addr0, %mem.write_data, %mem.write_en, %mem.clk, %mem.read_data, %mem.done = 
      calyx.memory @my_sram <[2] x 64> [1] : i1, i64, i1, i1, i64, i1

    calyx.wires {
      calyx.assign %mem.clk = %clk : i1
    }

    calyx.control {
    }
  }
}
```

Error: `'calyx.memory' op couldn't convert to core primitive`

#### Attempt 4: Manual Blackbox + `calyx.instance` (Workaround)

I manually created a dummy `"calyx.component"() {sym_name="sram_blackbox"}` and tried to instantiate it inside `@main`. I discovered that the error changes depending on the component order in the MLIR file, which points to a pass traversal / topological ordering bug.

```mlir
"builtin.module"() ({
  // Main component instantiating the blackbox SRAM
  "calyx.component"() <{function_type = (i64, i1, i1, i1, i1) -> (), portAttributes = [{}, {clk}, {reset}, {go}, {done}], portDirections = -16 : i5, portNames = ["in0", "clk", "reset", "go", "done"], sym_name = "main"}> ({
  ^bb0(%arg0: i64, %clk: i1, %reset: i1, %go: i1, %done: i1):
    // Instantiating the custom blackbox component
    %mem:8 = "calyx.instance"() <{componentName = @sram_blackbox, sym_name = "my_sram_inst"}> : () -> (i1, i1, i1, i1, i1, i64, i64, i1)

    "calyx.wires"() ({
    ^bb0:
      // Dummy assignment to prevent "empty component" verifier error
      "calyx.assign"(%done, %go) : (i1, i1) -> ()
    }) : () -> ()

    "calyx.control"() ({
    ^bb0:
    }) : () -> ()
  }) {toplevel} : () -> ()

  // Custom blackbox component definition
  "calyx.component"() <{function_type = (i1, i1, i1, i1, i1, i64, i64, i1) -> (), portAttributes = [{}, {go}, {clk}, {}, {reset}, {}, {}, {done}], portDirections = -64 : i8, portNames = ["addr0", "content_en", "clk", "write_en", "reset", "write_data", "read_data", "done"], sym_name = "sram_blackbox"}> ({
  ^bb0(%addr0: i1, %content_en: i1, %clk: i1, %write_en: i1, %reset: i1, %write_data: i64, %read_data: i64, %done: i1):
    "calyx.wires"() ({
      ^bb0:
      "calyx.assign"(%done, %content_en) : (i1, i1) -> ()
      "calyx.assign"(%read_data, %write_data) : (i64, i64) -> ()
    }) : () -> ()
    "calyx.control"() ({
      ^bb0:
    }) : () -> ()
  }) : () -> ()
}) {calyx.entrypoint = "main"} : () -> ()
```

Error: `error: 'calyx.instance' op couldn't convert to core primitive` and `error: failed to legalize operation 'calyx.instance' that was explicitly marked illegal: %2:8 = "calyx.instance"() <{componentName = @sram_blackbox, sym_name = "my_sram_inst"}> : () -> (i1, i1, i1, i1, i1, i64, i64, i1)`

```mlir
"builtin.module"() ({
  // 1. Custom blackbox component defined FIRST (Child)
  "calyx.component"() <{function_type = (i1, i1, i1, i1, i1, i64, i64, i1) -> (), portAttributes = [{}, {go}, {clk}, {}, {reset}, {}, {}, {done}], portDirections = -64 : i8, portNames = ["addr0", "content_en", "clk", "write_en", "reset", "write_data", "read_data", "done"], sym_name = "sram_blackbox"}> ({
  ^bb0(%addr0: i1, %content_en: i1, %clk: i1, %write_en: i1, %reset: i1, %write_data: i64, %read_data: i64, %done: i1):
    "calyx.wires"() ({
      ^bb0:
      "calyx.assign"(%done, %content_en) : (i1, i1) -> ()
      "calyx.assign"(%read_data, %write_data) : (i64, i64) -> ()
    }) : () -> ()
    "calyx.control"() ({
      ^bb0:
    }) : () -> ()
  }) : () -> ()

  // 2. Main component instantiating the blackbox SRAM (Parent)
  "calyx.component"() <{function_type = (i64, i1, i1, i1, i1) -> (), portAttributes = [{}, {clk}, {reset}, {go}, {done}], portDirections = -16 : i5, portNames = ["in0", "clk", "reset", "go", "done"], sym_name = "main"}> ({
  ^bb0(%arg0: i64, %clk: i1, %reset: i1, %go: i1, %done: i1):
    // Instantiating the custom blackbox component
    %mem:8 = "calyx.instance"() <{componentName = @sram_blackbox, sym_name = "my_sram_inst"}> : () -> (i1, i1, i1, i1, i1, i64, i64, i1)

    "calyx.wires"() ({
    ^bb0:
      // Dummy assignment to prevent "empty component" verifier error
      "calyx.assign"(%done, %go) : (i1, i1) -> ()
    }) : () -> ()

    "calyx.control"() ({
    ^bb0:
    }) : () -> ()
  }) {toplevel} : () -> ()
}) {calyx.entrypoint = "main"} : () -> ()
```

