  calyx.component @sram_blackbox_14_64(%addr0: i14, %content_en: i1 {go}, %clk: i1 {clk}, %write_en: i1, %reset: i1 {reset}, %write_data: i64) -> (%read_data: i64, %done: i1 {done}) {
