    %std_remu_pipe_0.clk, %std_remu_pipe_0.reset, %std_remu_pipe_0.go, %std_remu_pipe_0.left, %std_remu_pipe_0.right, %std_remu_pipe_0.out_remainder, %std_remu_pipe_0.done = calyx.std_remu_pipe @std_remu_pipe_0 : i1, i1, i1, i64, i64, i64, i1
